	t.Parallel()

	var (
		attempts int
		contents []string
	)
	cfg := pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{MaxAttempts: 3, RetryAllMethods: true},
	}
	client := newTestClientWithConfig(t, cfg, func(w http.ResponseWriter, r *http.Request) {
		attempts++
		file, _, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("FormFile error: %v", err)
		}
		defer file.Close()
		b, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		contents = append(contents, string(b))
		if attempts == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"slow down"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":5,"name":"doc.txt"}}`))
	})

	file, err := client.Files.AddFile(context.Background(), "doc.txt", strings.NewReader("payload"))
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if file.ID != 5 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
	for i, c := range contents {
		if c != "payload" {
			t.Fatalf("attempt %d content = %q, want %q", i+1, c, "payload")
		}
	}
}

